fn solve(input: Vec<char>) -> Vec<char> {
    // Helper function: map a digit character to its "good count".
    fn good_count(d: char) -> usize {
        match d {
            '0' => 2,
            '1' => 7,
            '2' => 2,
            '3' => 3,
            '4' => 3,
            '5' => 4,
            '6' => 2,
            '7' => 5,
            '8' => 1,
            '9' => 2,
            _ => 0, // unreachable for valid input
        }
    }

    // We only care about the first two characters.
    let c0 = input[0];
    let c1 = input[1];

    let count0 = good_count(c0);
    let count1 = good_count(c1);

    // Compute their product (1 through 49).
    let product = count0 * count1;

    // Convert to decimal characters, then append a newline.
    let mut out: Vec<char> = product
        .to_string()
        .chars()
        .collect();
    out.push('\n');

    out
}

// Example usage and simple test
fn main() {
    let input: Vec<char> = "12\n".chars().collect();
    let output = solve(input);
    let output_string: String = output.into_iter().collect();
    assert_eq!(output_string, "14\n");
    println!("Output was {:?}", output_string);
}